create extension if not exists pgcrypto;
create type public.listing_status as enum ('pending','approved','rejected');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, email text not null unique, role text not null default 'user' check (role in ('user','admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.listings (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, title text not null check (char_length(title) between 2 and 140), category text not null, max_duration_days smallint not null check (max_duration_days between 1 and 60), image_url text not null check (image_url ~* '^https://'), description text not null check (char_length(description) between 2 and 2000), status public.listing_status not null default 'pending', available boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.borrow_requests (id uuid primary key default gen_random_uuid(), listing_id uuid not null references public.listings(id) on delete cascade, borrower_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, owner_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check (status in ('pending','accepted','declined','returned','cancelled')), created_at timestamptz not null default now(), unique(listing_id, borrower_id));
create table public.messages (id uuid primary key default gen_random_uuid(), borrow_request_id uuid not null references public.borrow_requests(id) on delete cascade, sender_id uuid not null default auth.uid() references public.profiles(id), body text not null check(char_length(trim(body)) between 1 and 2000), created_at timestamptz not null default now());
create table public.member_locations (user_id uuid primary key references public.profiles(id) on delete cascade, latitude numeric(8,5) not null check(latitude between -90 and 90), longitude numeric(8,5) not null check(longitude between -180 and 180), updated_at timestamptz not null default now());
create table public.emergency_requests (id uuid primary key default gen_random_uuid(), requester_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, item_title text not null check(char_length(item_title) between 2 and 140), note text not null default '' check(char_length(note)<=500), latitude numeric(8,5) not null, longitude numeric(8,5) not null, expires_at timestamptz not null, created_at timestamptz not null default now());
create table public.emergency_recipients (emergency_request_id uuid references public.emergency_requests(id) on delete cascade, recipient_id uuid references public.profiles(id) on delete cascade, primary key(emergency_request_id,recipient_id));
create index listings_status_available_idx on public.listings(status,available); create index messages_request_created_idx on public.messages(borrow_request_id,created_at); create index emergency_expires_idx on public.emergency_requests(expires_at);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger listings_updated before update on public.listings for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.email !~* '^[^@[:space:]]+@srmist\.edu\.in$' then raise exception 'Only SRMIST email addresses are allowed'; end if; insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.listings enable row level security; alter table public.borrow_requests enable row level security; alter table public.messages enable row level security; alter table public.member_locations enable row level security; alter table public.emergency_requests enable row level security; alter table public.emergency_recipients enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy profiles_update_self on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role='user');
create policy listings_read on public.listings for select using((status='approved' and available) or owner_id=auth.uid() or public.is_admin()); create policy listings_insert on public.listings for insert with check(owner_id=auth.uid() or public.is_admin()); create policy listings_update on public.listings for update using(owner_id=auth.uid() or public.is_admin()) with check((owner_id=auth.uid() and status='pending' and available=false) or public.is_admin()); create policy listings_delete on public.listings for delete using(owner_id=auth.uid() or public.is_admin());
create policy requests_access on public.borrow_requests for select using(borrower_id=auth.uid() or owner_id=auth.uid() or public.is_admin()); create policy requests_insert on public.borrow_requests for insert with check(borrower_id=auth.uid() and owner_id<>(auth.uid()));
create policy messages_access on public.messages for select using(exists(select 1 from public.borrow_requests r where r.id=borrow_request_id and (r.borrower_id=auth.uid() or r.owner_id=auth.uid()))); create policy messages_insert on public.messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.borrow_requests r where r.id=borrow_request_id and (r.borrower_id=auth.uid() or r.owner_id=auth.uid())));
create policy location_self on public.member_locations for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy emergency_read on public.emergency_requests for select using(requester_id=auth.uid() or exists(select 1 from public.emergency_recipients er where er.emergency_request_id=id and er.recipient_id=auth.uid())); create policy recipients_read on public.emergency_recipients for select using(recipient_id=auth.uid() or exists(select 1 from public.emergency_requests e where e.id=emergency_request_id and e.requester_id=auth.uid()));
create or replace function public.create_emergency_request(p_item_title text,p_note text,p_latitude numeric,p_longitude numeric) returns jsonb language plpgsql security definer set search_path=public as $$ declare request_id uuid; recipient_count integer; begin if auth.uid() is null then raise exception 'Unauthorized'; end if; if char_length(trim(p_item_title)) not between 2 and 140 then raise exception 'Invalid item title'; end if; insert into public.emergency_requests(requester_id,item_title,note,latitude,longitude,expires_at) values(auth.uid(),trim(p_item_title),left(trim(coalesce(p_note,'')),500),p_latitude,p_longitude,now()+interval '15 minutes') returning id into request_id; insert into public.emergency_recipients(emergency_request_id,recipient_id) select request_id,l.user_id from public.member_locations l where l.user_id<>auth.uid() and l.updated_at>now()-interval '1 hour' and 6371*2*asin(sqrt(power(sin(radians(l.latitude-p_latitude)/2),2)+cos(radians(p_latitude))*cos(radians(l.latitude))*power(sin(radians(l.longitude-p_longitude)/2),2)))<=5; get diagnostics recipient_count=row_count; return jsonb_build_object('requestId',request_id,'recipientCount',recipient_count); end $$;
revoke all on function public.create_emergency_request(text,text,numeric,numeric) from public; grant execute on function public.create_emergency_request(text,text,numeric,numeric) to authenticated;
